2	use ratatui::style::{Color, Modifier, Style};
3	
4	use crate::options::SkimOptions;
5	
6	/// The color scheme of skim's UI
7	///
8	/// <pre>
9	/// +----------------+
10	/// | >selected line |  --> selected & normal(fg/bg) & matched
11	/// |> current line  |  --> cursor & current & current_match
12	/// |  normal line   |
13	/// |\ 8/10          |  --> spinner & info
14	/// |> query         |  --> prompt & query
15	/// +----------------+
16	/// </pre>
17	#[derive(Copy, Clone, Debug)]
18	pub struct ColorTheme {
19	    /// Non-selected lines and general text
20	    pub normal: Style,
21	    /// Matched text on non-current lines
22	    pub matched: Style,
23	    /// Current line, non-matched text
24	    pub current: Style,
25	    /// Current line, matched text
26	    pub current_match: Style,
27	    /// Query text/input
28	    pub query: Style,
29	    /// Spinner
30	    pub spinner: Style,
31	    /// Info (outside of spinner)
32	    pub info: Style,
33	    /// Prompt prefix
34	    pub prompt: Style,
35	    /// Cursor/Selector/pointer (prefix of current item)
36	    pub cursor: Style,
37	    /// Multi-selector/marker (prefix of selected items)
38	    pub selected: Style,
39	    /// Header lines
40	    pub header: Style,
41	    /// Border
42	    pub border: Style,
43	}
44	
45	impl Default for ColorTheme {
46	    /// Theme defaults to Dark256
47	    fn default() -> Self {
48	        ColorTheme::dark256()
49	    }
50	}
51	
52	#[allow(dead_code)]
53	impl ColorTheme {
54	    /// Setup the theme from the skim options
55	    #[must_use]
56	    pub fn init_from_options(options: &SkimOptions) -> ColorTheme {
57	        // register
58	        if let Some(color) = options.color.clone() {
59	            ColorTheme::from_options(&color)
60	        } else {
61	            // Check for NO_COLOR environment variable
62	            match std::env::var_os("NO_COLOR") {
63	                Some(no_color) if !no_color.is_empty() => ColorTheme::none(),
64	                _ => ColorTheme::dark256(),
65	            }
66	        }
67	    }
68	
69	    fn none() -> Self {
70	        let def = Style::default();
71	        Self {
72	            spinner: Style::default().bold(),
73	            normal: def,
74	            matched: def,
75	            current: def,
76	            current_match: def,
77	            query: def,
78	            info: def,
79	            prompt: def,
80	            cursor: def,
81	            selected: def,
82	            header: def,
83	            border: def,
84	        }
85	    }
86	
87	    fn bw() -> Self {
88	        let base = ColorTheme::none();
89	        ColorTheme {
90	            matched: base.matched.underlined(),
91	            current: base.current.reversed(),
92	            current_match: base.current_match.reversed().underlined(),
93	            ..base
94	        }
95	    }
96	
97	    fn default16() -> Self {
98	        let base = ColorTheme::none();
99	        ColorTheme {
100	            matched: base.matched.fg(Color::Green),
101	            current: base.current.fg(Color::Yellow),
102	            current_match: base.current_match.fg(Color::Green),
103	            spinner: base.spinner.fg(Color::Green),
104	            info: base.info.fg(Color::White),
105	            prompt: base.prompt.fg(Color::Blue),
106	            cursor: base.cursor.fg(Color::Red),
107	            selected: base.selected.fg(Color::Magenta),
108	            header: base.header.fg(Color::Cyan),
109	            border: base.border.fg(Color::Black),
110	            ..base
111	        }
112	    }
113	
114	    fn dark256() -> Self {
115	        let base = ColorTheme::none();
116	        ColorTheme {
117	            matched: base.matched.fg(Color::Indexed(108)).bg(Color::Indexed(0)),
118	            current: base.current.bg(Color::Indexed(236)),
