1	//! Layout computation for skim's TUI.
2	//!
3	//! The layout logic is split into two phases so that the expensive option-
4	//! inspection work is done only once (at startup and on option changes) while
5	//! the per-frame cost is reduced to a small number of cheap rect splits.
6	//!
7	//! * [`LayoutTemplate`] — built from [`SkimOptions`] and the static header
8	//!   height.  Stores pre-computed constraints and flags; no terminal-size
9	//!   dependency.  Stored on [`App`](super::App) and rebuilt only when options
10	//!   that affect layout change (e.g. [`TogglePreview`]).
11	//!
12	//! * [`AppLayout`] — produced by [`LayoutTemplate::apply`] from a concrete
13	//!   terminal [`Rect`].  Contains the final widget areas for one render frame.
14	//!   Computed in `render()` and cached on `App` so that code between renders
15	//!   (e.g. mouse hit-testing) can read it.
16	
17	use ratatui::layout::{Constraint, Direction as RatatuiDirection, Layout, Rect};
18	
19	use crate::SkimOptions;
20	use crate::tui::options::TuiLayout;
21	use crate::tui::statusline::InfoDisplay;
22	use crate::tui::{Direction, Size};
23	
24	// ---------------------------------------------------------------------------
25	// LayoutTemplate
26	// ---------------------------------------------------------------------------
27	
28	/// Orientation of the preview pane relative to the work area.
29	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
30	enum PreviewPlacement {
31	    /// Preview splits the full area horizontally (left / right of everything).
32	    Left,
33	    Right,
34	    /// Preview splits the full area vertically (above / below everything).
35	    Up,
36	    Down,
37	    /// No preview.
38	    None,
39	}
40	
41	/// Pre-computed layout descriptor built from [`SkimOptions`].
42	///
43	/// Contains everything needed to split a concrete [`Rect`] into widget areas,
44	/// but contains no coordinates itself — those only appear in [`AppLayout`].
45	/// Build with [`LayoutTemplate::from_options`] and store on
46	/// [`App`](super::App); call [`LayoutTemplate::apply`] in every render.
47	#[derive(Debug, Clone)]
48	pub struct LayoutTemplate {
49	    /// Whether the header widget should be rendered at all.
50	    show_header: bool,
51	    /// Where the preview pane is placed relative to the rest of the UI.
52	    preview_placement: PreviewPlacement,
53	    /// Whether the work layout emits slots in reverse order `[input, header,
54	    /// list]` instead of the default `[list, header, input]`.
55	    work_layout_reversed: bool,
56	    /// Pre-built [`Layout`] for carving the preview out of the full area
57	    /// (step 1).  `None` when no preview is visible.
58	    preview_layout: Option<Layout>,
59	    /// Pre-built [`Layout`] for splitting the work area into three slots.
60	    ///
61	    /// When `work_layout_reversed` is `false` the slots map to
62	    /// `[list, header, input]`; when `true` they map to
63	    /// `[input, header, list]`.  Applied in step 2 of [`Self::apply`].
64	    work_layout: Layout,
65	}
66	
67	impl LayoutTemplate {
68	    /// Build a [`LayoutTemplate`] from [`SkimOptions`] and the static header
69	    /// height (content rows only, excluding any border rows).
70	    ///
71	    /// `header_height` should come from
72	    /// [`Header::height()`](super::header::Header::height), which returns a
73	    /// value fixed at construction time from `options.header_lines` and the
74	    /// line-count of `options.header`.
75	    #[must_use]
76	    pub fn from_options(options: &SkimOptions, header_height: u16) -> Self {
77	        let has_border = options.border.is_some();
78	
79	        // Rows consumed by the input widget.
80	        let input_rows: u16 = if has_border {
81	            3 // 1 content + 2 border rows
82	        } else {
83	            1 + u16::from(options.info == InfoDisplay::Default)
84	        };
85	
86	        // Rows consumed by the header widget.
87	        let show_header = options.header.is_some() || options.header_lines > 0;
88	        let header_rows: u16 = if show_header {
89	            if has_border { header_height + 2 } else { header_height }
90	        } else {
91	            0
92	        };
93	
94	        // Preview placement and layout.
95	        let preview_visible = (options.preview.is_some() || options.preview_fn.is_some())
96	            && !options.preview_window.hidden
97	            && !matches!(options.preview_window.size, Size::Fixed(0));
98	
99	        let (preview_placement, preview_layout) = if preview_visible {
100	            let (preview_c, rest_c) = size_to_constraint(options.preview_window.size);
101	            let placement = match options.preview_window.direction {
102	                Direction::Left => PreviewPlacement::Left,
103	                Direction::Right => PreviewPlacement::Right,
104	                Direction::Up => PreviewPlacement::Up,
105	                Direction::Down => PreviewPlacement::Down,
106	            };
107	            let layout = match placement {
108	                PreviewPlacement::Left => Layout::new(RatatuiDirection::Horizontal, [preview_c, rest_c]),
109	                PreviewPlacement::Right => Layout::new(RatatuiDirection::Horizontal, [rest_c, preview_c]),
110	                PreviewPlacement::Up => Layout::new(RatatuiDirection::Vertical, [preview_c, rest_c]),
111	                PreviewPlacement::Down => Layout::new(RatatuiDirection::Vertical, [rest_c, preview_c]),
112	                PreviewPlacement::None => unreachable!(),
113	            };
114	            (placement, Some(layout))
115	        } else {
116	            (PreviewPlacement::None, None)
117	        };
118	
119	        // Work-area layout: single 3-way vertical split into [list, header, input].
120	        //
121	        // For Default / ReverseList: slots are [list, header, input] top-to-bottom.
122	        // For Reverse:               slots are [input, header, list] top-to-bottom.
123	        let non_list_rows = input_rows + header_rows;
124	        let work_layout_reversed = options.layout == TuiLayout::Reverse;
125	        let work_layout = if show_header {
126	            match options.layout {
127	                TuiLayout::Default | TuiLayout::ReverseList => Layout::vertical([
128	                    Constraint::Fill(1),
129	                    Constraint::Length(header_rows),
130	                    Constraint::Length(input_rows),
131	                ]),
132	                TuiLayout::Reverse => Layout::vertical([
133	                    Constraint::Length(input_rows),
134	                    Constraint::Length(header_rows),
135	                    Constraint::Fill(1),
136	                ]),
137	            }
138	        } else {
139	            match options.layout {
140	                TuiLayout::Default | TuiLayout::ReverseList => Layout::vertical([
141	                    Constraint::Fill(1),
142	                    Constraint::Length(0),
143	                    Constraint::Length(non_list_rows),
144	                ]),
145	                TuiLayout::Reverse => Layout::vertical([
146	                    Constraint::Length(non_list_rows),
147	                    Constraint::Length(0),
148	                    Constraint::Fill(1),
149	                ]),
150	            }
151	        };
152	
153	        Self {
154	            show_header,
155	            preview_placement,
156	            work_layout_reversed,
157	            preview_layout,
158	            work_layout,
159	        }
160	    }
161	
162	    /// Apply this template to a concrete terminal `area`, producing the
163	    /// absolute [`AppLayout`] for one render frame.
164	    #[must_use]
165	    pub fn apply(&self, area: Rect) -> AppLayout {
166	        // ── Step 1: carve out the preview from the full area ─────────────────
167	        let (work_area, preview_area): (Rect, Option<Rect>) = match &self.preview_layout {
168	            Some(layout) => {
169	                let [a, b]: [Rect; 2] = layout.areas(area);
170	                match self.preview_placement {
171	                    // preview is the first segment for Left / Up
172	                    PreviewPlacement::Left | PreviewPlacement::Up => (b, Some(a)),
173	                    // preview is the second segment for Right / Down
174	                    _ => (a, Some(b)),
175	                }
176	            }
177	            None => (area, None),
178	        };
179	
180	        // ── Step 2: split work_area into list / header / input in one pass ───
181	        //
182	        // Slots are [list, header, input] when `work_layout_reversed` is false,
183	        // or [input, header, list] when true (Reverse layout).
184	        let [slot0, slot1, slot2]: [Rect; 3] = self.work_layout.areas(work_area);
185	
186	        let (list_area, header_slot, input_area) = if self.work_layout_reversed {
187	            (slot2, slot1, slot0)
188	        } else {
189	            (slot0, slot1, slot2)
190	        };
191	
192	        let header_area = if self.show_header { Some(header_slot) } else { None };
193	
194	        AppLayout {
195	            list_area,
196	            input_area,
197	            header_area,
198	            preview_area,
199	        }
200	    }
201	}
202	
203	// ---------------------------------------------------------------------------
204	// AppLayout
205	// ---------------------------------------------------------------------------
206	
207	/// Concrete widget areas for one render frame, produced by
208	/// [`LayoutTemplate::apply`].
209	///
210	/// Cached on [`App`](super::App) after each render so that code between frames
211	/// (e.g. mouse hit-testing in `handle_mouse`) can read the last known areas.
212	#[derive(Debug, Clone, PartialEq, Eq)]
213	pub struct AppLayout {
214	    /// Area for the item list widget.
215	    pub list_area: Rect,
216	    /// Area for the input / prompt widget.
217	    pub input_area: Rect,
218	    /// Area for the header widget (`None` when no header is shown).
219	    pub header_area: Option<Rect>,
220	    /// Area for the preview pane (`None` when preview is hidden or disabled).
221	    pub preview_area: Option<Rect>,
222	}
223	
224	impl AppLayout {
225	    /// Convenience wrapper: build a [`LayoutTemplate`] from `options` and
226	    /// `header_height`, then immediately apply it to `area`.
227	    ///
228	    /// Prefer storing the [`LayoutTemplate`] and calling
229	    /// [`LayoutTemplate::apply`] directly when the template can be reused
230	    /// across frames.
231	    #[must_use]
232	    pub fn compute(area: Rect, options: &SkimOptions, header_height: u16) -> Self {
233	        LayoutTemplate::from_options(options, header_height).apply(area)
234	    }
235	}
236	
237	// ---------------------------------------------------------------------------
238	// Helper
239	// ---------------------------------------------------------------------------
240	
241	fn size_to_constraint(size: Size) -> (Constraint, Constraint) {
242	    match size {
243	        Size::Fixed(n) => (Constraint::Length(n), Constraint::Fill(1)),
244	        Size::Percent(p) => (Constraint::Percentage(p), Constraint::Fill(1)),
245	        Size::Neg(n) => (Constraint::Fill(1), Constraint::Length(n)),
246	    }
247	}
