4	use std::process::{Command, ExitStatus, Stdio};
5	
6	pub fn is_available() -> bool {
7	    cfg!(unix) && std::env::var("TMUX").is_ok() && which::which("tmux").is_ok()
8	}
9	
10	pub(super) struct TmuxPopup {
11	    cmd: Command,
12	}
13	
14	impl TmuxPopup {
15	    fn build(options: &SkimOptions) -> Self {
16	        let arg = options.popup.as_ref().expect("this arg should be present to get here");
17	        let mut cmd = Command::new(
18	            which::which("tmux").expect("tmux not found in path. This should have been caught by is_available"),
19	        );
20	        cmd.arg("display-popup").arg("-E").args([
21	            "-d",
22	            &std::env::current_dir()
23	                .ok()
24	                .map_or(".".to_string(), |d| d.to_string_lossy().to_string()),
25	        ]);
26	
27	        let border = {
28	            use crate::tui::BorderType::{Plain, Rounded, Thick};
29	            if options.no_border {
30	                "none"
31	            } else {
32	                match options.border {
33	                    None | Some(Plain) => "single",
34	                    Some(Rounded) => "rounded",
35	                    Some(Thick) => "heavy",
36	                    Some(_) => "double",
37	                }
38	            }
39	        };
40	
41	        let (raw_dir, size) = arg.split_once(',').unwrap_or((arg, "50%"));
42	        let dir = PopupWindowDir::from(raw_dir);
43	        let (height, width) = if let Some((lhs, rhs)) = size.split_once(',') {
44	            match dir {
45	                PopupWindowDir::Center | PopupWindowDir::Left | PopupWindowDir::Right => (rhs, lhs),
46	                PopupWindowDir::Top | PopupWindowDir::Bottom => (lhs, rhs),
47	            }
48	        } else {
49	            match dir {
50	                PopupWindowDir::Left | PopupWindowDir::Right => ("100%", size),
51	                PopupWindowDir::Top | PopupWindowDir::Bottom => (size, "100%"),
52	                PopupWindowDir::Center => (size, size),
53	            }
54	        };
55	
56	        let (x, y) = match dir {
57	            PopupWindowDir::Center => ("C", "C"),
58	            PopupWindowDir::Top => ("C", "0%"),
59	            PopupWindowDir::Bottom => ("C", "100%"),
60	            PopupWindowDir::Left => ("0%", "C"),
61	            PopupWindowDir::Right => ("100%", "C"),
62	        };
63	
64	        cmd.args(["-h", height])
65	            .args(["-w", width])
66	            .args(["-x", x])
67	            .args(["-y", y])
68	            .args(["-b", border]);
69	
70	        Self { cmd }
71	    }
72	}
73	
74	impl SkimPopup for TmuxPopup {
75	    fn from_options(options: &SkimOptions) -> Box<dyn SkimPopup> {
76	        Box::new(Self::build(options)) as Box<dyn SkimPopup>
77	    }
78	
79	    fn add_env(&mut self, key: &str, value: &str) {
80	        self.cmd.args(["-e", &format!("{key}={value}")]);
81	    }
82	
83	    fn run_and_wait(&mut self, command: &str) -> std::io::Result<ExitStatus> {
84	        debug!("tmux command: {command:?}");
85	        self.cmd.args(["sh", "-c", command]);
86	
87	        debug!("tmux full command: {:?}", self.cmd);
88	        self.cmd
89	            .stdout(Stdio::null())
90	            .stderr(Stdio::null())
91	            .stdin(Stdio::null())
92	            .status()
93	    }
94	}
