        assert_eq!(get_flag(&a, "-h"), Some("30%"));
        assert_eq!(get_flag(&a, "-w"), Some("100%"));
        assert_eq!(get_flag(&a, "-x"), Some("C"));
        assert_eq!(get_flag(&a, "-y"), Some("100%"));
    }

