content:
1	//! Provides helpers to easily generate shell completions
2	use clap::CommandFactory;
3	
4	use crate::SkimOptions;
5	
6	/// Available shells for completion generation
7	#[derive(Clone, clap::ValueEnum, PartialEq, Debug)]
8	pub enum Shell {
9	    /// Bourne Again `SHell`
10	    Bash,
11	    /// Elvish shell
12	    Elvish,
13	    /// Friendly Interactive `SHell`
14	    Fish,
15	    /// Nushell (nu)
16	    Nushell,
17	    /// `PowerShell`
18	    PowerShell,
19	    /// Zsh
20	    Zsh,
21	}
22	
23	/// Generate the completion and write it to stdout
24	pub fn generate_completions(sh: &Shell) {
25	    use Shell::{Bash, Elvish, Fish, Nushell, PowerShell, Zsh};
26	    let output = &mut std::io::stdout();
27	    let cmd = &mut SkimOptions::command();
28	    let bin_name = "sk";
